import{_ as t,o as n,c as r,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Encrypting Data in Ceph- An Overview and Opportunities - David Mohren, 45Drives","description":"","frontmatter":{"title":"Encrypting Data in Ceph- An Overview and Opportunities - David Mohren, 45Drives","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Data Encryption","Server-Side Encryption","Client-Side Encryption","Security"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Encrypting_Data_in_Ceph_-_An_Overview_and_Opportunities_-_David_Mohren_45Drives.md","filePath":"posts/2025/Encrypting_Data_in_Ceph_-_An_Overview_and_Opportunities_-_David_Mohren_45Drives.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Encrypting_Data_in_Ceph_-_An_Overview_and_Opportunities_-_David_Mohren_45Drives.md"};function l(a,i,s,_,p,g){return n(),r("div",null,[...i[0]||(i[0]=[e('<p>会议纪要：Ceph 数据加密与 SEF 概述及改进机会</p><p><strong>会议主题</strong>: Ceph 数据加密与 SEF 概述及改进机会<br><strong>主讲人</strong>: David Mohren<br><strong>日期</strong>: 2025年1月23日</p><h4 id="_1-会议概述" tabindex="-1">1. <strong>会议概述</strong> <a class="header-anchor" href="#_1-会议概述" aria-label="Permalink to &quot;1. **会议概述**&quot;">​</a></h4><ul><li>David Mohren 介绍了 Ceph 中的数据加密技术，重点讨论了服务器端加密（Server-Side Encryption）和客户端加密（Client-Side Encryption）的实现方式。</li><li>目标是消除加密技术的神秘感，提供代码片段和实现细节，帮助与会者更好地理解加密过程。</li><li>讨论了当前加密方案的优缺点，并提出了改进建议。</li></ul><h4 id="_2-主要议题" tabindex="-1">2. <strong>主要议题</strong> <a class="header-anchor" href="#_2-主要议题" aria-label="Permalink to &quot;2. **主要议题**&quot;">​</a></h4><ul><li><strong>服务器端加密（Server-Side Encryption）</strong>： <ul><li><strong>OSD 加密</strong>：Ceph 使用 Bluestore 和 Linux 内核的加密功能，通过配置硬盘驱动器实现数据加密。</li><li><strong>RGW 加密</strong>：RGW 支持对象存储加密，使用外部密钥存储管理密钥，加密模式为 AES-256-CBC。</li><li><strong>常见问题</strong>：密钥存储在外部组件中可能导致单点故障，密钥在 Monitor 中以明文存储存在安全隐患。</li></ul></li><li><strong>客户端加密（Client-Side Encryption）</strong>： <ul><li><strong>RBD 加密</strong>：RBD 支持客户端加密，使用 LUKS 标准。用户可以在用户空间库中格式化并加载加密密钥，但存在密钥管理问题。</li><li><strong>CephFS 加密</strong>：CephFS 支持 FSCRYPT，文件系统级别的加密工具，使用 AES-56-XTS 加密文件内容。</li></ul></li><li><strong>加密方案的改进</strong>： <ul><li><strong>完整性问题</strong>：当前的加密方案在数据完整性方面存在缺陷，修改加密数据后系统不会报错，可能导致数据损坏。</li><li><strong>提议改进</strong>：引入 AEAD（Authenticated Encryption with Associated Data）加密模式，如 AES-GCM，以确保数据的完整性和真实性。</li><li><strong>RADOS 级别的加密</strong>：建议在 RADOS 层实现加密，统一加密逻辑，减少重复开发工作，提高系统安全性。</li></ul></li></ul><h4 id="_3-决定事项" tabindex="-1">3. <strong>决定事项</strong> <a class="header-anchor" href="#_3-决定事项" aria-label="Permalink to &quot;3. **决定事项**&quot;">​</a></h4><ul><li><strong>加密方案的改进</strong>： <ul><li>引入 AEAD 加密模式（如 AES-GCM）以增强数据完整性。</li><li>在 RADOS 层统一加密逻辑，减少不同组件之间的重复开发。</li></ul></li><li><strong>密钥管理改进</strong>： <ul><li>解决密钥在外部存储中的单点故障问题。</li><li>加强密钥在 Monitor 中的安全性，避免明文存储。</li></ul></li></ul><h4 id="_4-后续行动计划" tabindex="-1">4. <strong>后续行动计划</strong> <a class="header-anchor" href="#_4-后续行动计划" aria-label="Permalink to &quot;4. **后续行动计划**&quot;">​</a></h4><ul><li><strong>开发团队</strong>： <ul><li>评估 AEAD 加密模式的可行性，并在 RADOS 层实现统一加密逻辑。</li><li>改进密钥管理方案，确保密钥存储的安全性和高可用性。</li></ul></li><li><strong>测试与验证</strong>： <ul><li>进行性能测试，评估 AEAD 加密模式对系统性能的影响。</li><li>验证 RADOS 层加密的可行性和安全性。</li></ul></li></ul><h4 id="_5-会议总结" tabindex="-1">5. <strong>会议总结</strong> <a class="header-anchor" href="#_5-会议总结" aria-label="Permalink to &quot;5. **会议总结**&quot;">​</a></h4><ul><li>本次会议详细讨论了 Ceph 中的数据加密技术，分析了现有方案的优缺点，并提出了改进建议。</li><li>重点在于引入 AEAD 加密模式以增强数据完整性，并在 RADOS 层统一加密逻辑，减少重复开发工作。</li><li>后续将由开发团队负责具体实现，并进行相关测试与验证。</li></ul><p><strong>会议结束</strong></p>',13)])])}const u=t(o,[["render",l]]);export{h as __pageData,u as default};
